#!/usr/bin/env bash
set -euo pipefail
DEST="/opt/taskbounty-autobot"
if [ "$(id -u)" -ne 0 ]; then
  echo "Run as root: sudo bash taskbounty-autobot-v4-install.sh"
  exit 1
fi
export DEBIAN_FRONTEND=noninteractive
apt-get update
apt-get install -y ca-certificates curl gnupg
if ! command -v docker >/dev/null 2>&1 || ! docker compose version >/dev/null 2>&1; then
  install -m 0755 -d /etc/apt/keyrings
  . /etc/os-release
  curl -fsSL "https://download.docker.com/linux/$ID/gpg" | gpg --dearmor -o /etc/apt/keyrings/docker.gpg
  chmod a+r /etc/apt/keyrings/docker.gpg
  ARCH=$(dpkg --print-architecture)
  echo "deb [arch=$ARCH signed-by=/etc/apt/keyrings/docker.gpg] https://download.docker.com/linux/$ID $VERSION_CODENAME stable" > /etc/apt/sources.list.d/docker.list
  apt-get update
  apt-get install -y docker-ce docker-ce-cli containerd.io docker-buildx-plugin docker-compose-plugin
  systemctl enable --now docker
fi
mkdir -p "$DEST"
OLD_ENV=""
if [ -f "$DEST/.env" ]; then
  OLD_ENV=$(mktemp)
  cp "$DEST/.env" "$OLD_ENV"
fi
PAYLOAD=$(mktemp)
cat > "$PAYLOAD.b64" <<'PAYLOAD_B64'

PAYLOAD_B64
base64 -d "$PAYLOAD.b64" > "$PAYLOAD"
TMPDIR=$(mktemp -d)
tar -xzf "$PAYLOAD" -C "$TMPDIR"
cp -a "$TMPDIR/taskbounty-autobot/." "$DEST/"
rm -rf "$TMPDIR" "$PAYLOAD" "$PAYLOAD.b64"
if [ -n "$OLD_ENV" ]; then
  cp "$OLD_ENV" "$DEST/.env"
  rm -f "$OLD_ENV"
else
  cp "$DEST/.env.example" "$DEST/.env"
fi
chmod +x "$DEST"/*.sh || true
cd "$DEST"
docker compose build --pull
echo
echo "TaskBounty Autobot v4 installed at $DEST"
echo "Next one-time step: cd $DEST && bash LOGIN_ONCE.sh"
